target.css:
:root {
  --ink: #20242b;
  --muted: #69717d;
  --paper: #fffdf8;
  --line: #ddd9d0;
  --purple: #5d4a96;
  --lavender: #eee9fb;
  --gold: #c18a35;
  --warm-white: #f8f3e8;
}

.listening-card {
  box-sizing: border-box;
  width: 480px;
  padding: 16px;
  color: var(--ink);
  background: var(--paper);
  border: 1px solid var(--line);
  border-top: 4px solid var(--purple);
  border-radius: 14px;
}

.card-header {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 12px;
}

.eyebrow,
.label {
  margin: 0;
  color: var(--purple);
  font-size: 11px;
  font-weight: 700;
  letter-spacing: 0.08em;
  line-height: 1.2;
  text-transform: uppercase;
}

.card-header h1 {
  margin: 4px 0 0;
  font-size: 21px;
  line-height: 1.1;
}

.status {
  padding: 5px 9px;
  color: var(--purple);
  background: var(--lavender);
  border-radius: 999px;
  font-size: 12px;
  font-weight: 700;
}

.now-playing {
  display: grid;
  grid-template-columns: 70px 1fr;
  align-items: center;
  gap: 12px;
  margin: 15px 0;
  padding: 10px;
  background: var(--warm-white);
  border-radius: 10px;
}

.album-art {
  position: relative;
  display: grid;
  width: 70px;
  height: 70px;
  margin: 0;
  place-items: center;
  overflow: hidden;
  color: var(--paper);
  background: var(--purple);
  border-radius: 8px;
}

.album-art::before {
  position: absolute;
  width: 46px;
  height: 46px;
  border: 2px solid var(--lavender);
  border-radius: 50%;
  content: "";
}

.album-art span {
  z-index: 1;
  padding: 3px 5px;
  background: var(--gold);
  border-radius: 3px;
  font-size: 10px;
  font-weight: 700;
}

.track-info h2 {
  margin: 3px 0 2px;
  font-size: 18px;
  line-height: 1.1;
}

.artist {
  margin: 0;
  color: var(--muted);
  font-size: 13px;
}

.details {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 8px;
  margin: 0;
  padding: 0;
  list-style: none;
}

.details li {
  display: flex;
  flex-direction: column;
  gap: 3px;
  padding-left: 9px;
  border-left: 2px solid var(--gold);
}

.details strong {
  font-size: 13px;
  line-height: 1.2;
}

.details span {
  color: var(--muted);
  font-size: 12px;
}

.card-footer {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  margin-top: 15px;
  padding-top: 12px;
  border-top: 1px solid var(--line);
}

.card-footer p {
  margin: 0;
  color: var(--muted);
  font-size: 12px;
}

.reserve-button {
  padding: 8px 12px;
  color: var(--paper);
  background: var(--purple);
  border: 0;
  border-radius: 7px;
  font-size: 13px;
  font-weight: 700;
}

